/** Small text utilities. */
public final class TextTools {

    private TextTools() {}

    /** The number of words in the text, words being separated by whitespace. */
    public static int wordCount(String text) {
        String trimmed = text.trim();
        if (trimmed.isEmpty()) {
            return 0;
        }
        return trimmed.split("\\s+").length;
    }
}
/** Plain checks, no framework: run with `java -cp out TextToolsTest`; exits 1 on the first failure. */
public final class TextToolsTest {

    public static void main(String[] args) {
        check(TextTools.wordCount("one two three") == 3, "three words");
        check(TextTools.wordCount("  spaced   out  ") == 2, "extra spaces");
        check(TextTools.wordCount("") == 0, "empty text");
        check(TextTools.wordCount("   ") == 0, "blank text");
        check(TextTools.wordCount(" \t\n ") == 0, "whitespace-only text with tab and line break");
        check(TextTools.wordCount("a\tb") == 2, "tab separator");
        check(TextTools.wordCount("a\nb") == 2, "line break separator");
        System.out.println("All checks passed");
    }

    static void check(boolean ok, String what) {
        if (!ok) {
            System.out.println("FAILED: " + what);
            System.exit(1);
        }
    }
}
